skeletonStyle:
html,
body,
.i-renderer-app__container,
.i-website-skeleton__section {
  height: 100%;
  margin: 0;
  padding: 0;
}
.i-website-skeleton__image {width: 240px; height: 240px; margin-bottom: 20px;border-radius: var(--el-border-radius-base);}
.i-website-skeleton__text1 {width: 60%; height: 18px;margin-bottom: 10px;border-radius: var(--el-border-radius-base);}
.i-website-skeleton__text2 {width: 50%; height: 18px;margin-bottom: 10px;border-radius: var(--el-border-radius-base);}
.i-website-skeleton__text3 {width: 80%; height: 18px;margin-bottom: 10px;border-radius: var(--el-border-radius-base);}
.i-website-skeleton__text4 {width: 90%; height: 18px;margin-bottom: 10px;border-radius: var(--el-border-radius-base);}
html.pc.horizontal .i-website-skeleton__aside {display: none}
html.pc.horizontal .i-website-skeleton__section {margin-left: 0}
html.pc .i-website-skeleton__header,
html.mobile .i-website-skeleton__header {
  height: 60px;
  border-bottom: 1px solid #dcdfe6;
}
html.pc .i-website-skeleton__section {
  display: flex;
  flex-direction: column;
}
html.pc .i-website-skeleton__main {
  flex: 1;
  margin: 20px;
}
html.pc .i-website-skeleton__footer,
html.mobile .i-website-skeleton__footer {
  height: 50px;
  border-top: 1px solid #dcdfe6;
  color: #909399;
  line-height: 50px;
  text-align: center;
  font-size: 14px;
}
html.mobile .i-website-skeleton__main,
html.pc .loading.i-website-skeleton__main,
html.pc .loading.i-website-skeleton__header,
html.pc .loading.i-website-skeleton__footer,
.i-website-skeleton__image,
.i-website-skeleton__text1,
.i-website-skeleton__text2,
.i-website-skeleton__text3,
.i-website-skeleton__text4 {
  background-color: #f0f2f5;
  background: linear-gradient(90deg,#f0f2f5 25%,#e6e8eb 37%,#f0f2f5 63%);
  background-size: 200% 100%;
  background-position-x: 180%;
  animation: 1s loading ease-in-out infinite;
}
html.mobile .i-website-skeleton__section {
  display: flex;
  flex-direction: column;
}
html.mobile .i-website-skeleton__main {
  flex: 1;
  margin: 20px;
}
@keyframes loading {
  to {
    background-position-x: -20%;
  }
}
